import subprocess

# Read the full file
result = subprocess.run(['cat', 'boltons/iterutils.py'], capture_output=True, text=True)
content = result.stdout
lines = content.split('\n')

# Find the exact line numbers we need to modify
for i, line in enumerate(lines):
    if 'def remap(root' in line:
        print(f"remap starts at line {i+1}")
    if 'reraise_visit = kwargs.pop' in line:
        print(f"reraise_visit at line {i+1}: {line.strip()}")
